package com.bank.delegation;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;

public class DelegationMonitor {

    public List<BigDecimal> levelAverages(LimitNode root) {
        List<BigDecimal> averages = new ArrayList<>();
        if (root == null) return averages;

        Queue<LimitNode> queue = new LinkedList<>();
        queue.offer(root);
        while (!queue.isEmpty()) {
            int levelSize = queue.size();
            BigDecimal sum = BigDecimal.ZERO;
            for (int i = 0; i < levelSize; i++) {
                LimitNode node = queue.poll();
                sum = sum.add(node.limit);                 // money-safe accumulation
                if (node.left != null) queue.offer(node.left);
                if (node.right != null) queue.offer(node.right);
            }
            // Divide with explicit scale + rounding (never use double for money).
            averages.add(sum.divide(new BigDecimal(levelSize), 2, RoundingMode.HALF_UP));
        }
        return averages;
    }
}
