        LimitNode root = new LimitNode("100000");
        root.left = new LimitNode("50000");
        root.right = new LimitNode("70000");
        root.left.left = new LimitNode("20000");
        root.left.right = new LimitNode("30000");
        root.right.right = new LimitNode("40000");

        log.info("Average approval limit per rank: " + new DelegationMonitor().levelAverages(root));
    }
}
